"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useState } from "react";

import { CircleCheckIcon } from "@/components/blocks/parts/icons";
import { HoldToConfirmButton } from "@/components/motion/hold-to-confirm";
import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { InfoIcon } from "./icons";
import { CANCEL_STEPS, LOWER_PLAN, pauseEnds, PLAN, REASONS, type ReasonId } from "./cancel-flow/data";
import { OfferPanel } from "./cancel-flow/offer-panel";
import { ReasonCards } from "./cancel-flow/reason-cards";
import { SpringHeight } from "./shared/spring-height";
import { StepRail } from "./shared/step-rail";

type Outcome = { kind: "kept"; message: string } | { kind: "cancelled" } | null;

const ACCEPT_LABEL = { price: `Switch to ${LOWER_PLAN.name}`, unused: "Pause my plan", feature: "Send and keep my plan", switching: "Download my data" } satisfies Record<ReasonId, string>;

/**
 * Cancelling a plan in three steps: the reason, an option that answers it,
 * then a hold-to-cancel. Nothing changes until the last step, and the way
 * to cancel stays in view at every step, so an option is never a wall.
 */
export function CancelFlow({ className }: { className?: string }) {
  const [step, setStep] = useState(0);
  const [direction, setDirection] = useState(1);
  const [reason, setReason] = useState<ReasonId | null>(null);
  const [pauseMonths, setPauseMonths] = useState(2);
  const [note, setNote] = useState("");
  const [outcome, setOutcome] = useState<Outcome>(null);
  const [downloaded, setDownloaded] = useState(false);
  const titleId = useId();
  const railId = useId();
  const reduceMotion = useReducedMotion();

  const go = (next: number) => {
    setDirection(next > step ? 1 : -1);
    setStep(next);
  };

  const reset = () => {
    setOutcome(null);
    setStep(0);
    setReason(null);
    setDownloaded(false);
  };

  const accept = () => {
    if (reason === "price") setOutcome({ kind: "kept", message: `You are on ${LOWER_PLAN.name} from ${PLAN.renews}, at $${LOWER_PLAN.price} a month.` });
    else if (reason === "unused") setOutcome({ kind: "kept", message: `Your plan is paused until ${pauseEnds(pauseMonths)}. Nothing is billed until then.` });
    else if (reason === "feature") setOutcome({ kind: "kept", message: "Thanks. The product team has your note, and your plan stays as it is." });
    else if (reason === "switching") setDownloaded(true);
  };

  const offset = reduceMotion ? 0 : `${2 * direction}rem`;
  const back = reduceMotion ? 0 : `${-2 * direction}rem`;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
        <div>
          <h2 id={titleId} className="text-base font-semibold">
            Cancel your plan
          </h2>
          <p className="text-sm text-muted-foreground">
            {PLAN.name} plan, {PLAN.seats} seats, ${PLAN.price} a month, renews {PLAN.renews}
          </p>
        </div>
      </header>

      {outcome ? (
        <div role="status" className="flex flex-col items-start gap-3 p-6">
          <CircleCheckIcon aria-hidden="true" className="size-6 text-chart-2" />
          <h3 className="text-base font-semibold">{outcome.kind === "kept" ? "Your plan is updated" : "Your plan is cancelled"}</h3>
          <p className="text-sm text-muted-foreground">
            {outcome.kind === "kept"
              ? outcome.message
              : `You keep full access until ${PLAN.renews}. Your data stays for 90 days after that, so you can come back.`}
          </p>
          <Button variant="outline" onClick={reset}>
            {outcome.kind === "kept" ? "Done" : "Keep my plan after all"}
          </Button>
        </div>
      ) : (
        <div className="flex flex-col gap-5 p-5">
          <StepRail steps={CANCEL_STEPS} current={step} railId={railId} />
          <SpringHeight>
            <AnimatePresence mode="wait" initial={false}>
              <motion.div
                key={step}
                initial={{ opacity: 0, x: offset }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: back }}
                transition={{ duration: reduceMotion ? 0 : 0.2, ease: "easeOut" }}
                className="flex flex-col gap-4 pb-1"
              >
                {step === 0 ? (
                  <>
                    <h3 className="text-base font-semibold">Why are you cancelling?</h3>
                    <ReasonCards reasons={REASONS} value={reason} onChange={setReason} />
                    <p className="flex items-center gap-2 text-xs text-muted-foreground">
                      <InfoIcon aria-hidden="true" className="size-3.5" />
                      Nothing changes until the last step.
                    </p>
                  </>
                ) : null}
                {step === 1 && reason ? (
                  <>
                    <OfferPanel reason={reason} pauseMonths={pauseMonths} onPauseMonths={setPauseMonths} note={note} onNote={setNote} />
                    <p role="status" className="text-xs text-muted-foreground">
                      {downloaded ? "Your export is ready: 4 files, 2.3 MB." : ""}
                    </p>
                  </>
                ) : null}
                {step === 2 ? (
                  <>
                    <h3 className="text-base font-semibold">Before you go</h3>
                    <ul className="flex list-disc flex-col gap-1.5 pl-5 text-sm">
                      <li>Your team keeps full access until {PLAN.renews}.</li>
                      <li>Patients can no longer book online after that day.</li>
                      <li>We keep your data for 90 days, then delete it.</li>
                    </ul>
                  </>
                ) : null}
              </motion.div>
            </AnimatePresence>
          </SpringHeight>

          <div className="flex flex-wrap items-center justify-between gap-2 border-t border-border pt-4">
            <Button variant="ghost" onClick={() => go(step - 1)} disabled={step === 0}>
              Back
            </Button>
            <div className="flex flex-wrap justify-end gap-2">
              {step === 0 ? (
                <Button onClick={() => go(1)} disabled={!reason}>
                  Continue
                </Button>
              ) : null}
              {step === 1 && reason ? (
                <>
                  <Button variant="outline" onClick={() => go(2)}>
                    Continue to cancel
                  </Button>
                  <Button onClick={accept} disabled={reason === "feature" && note.trim().length === 0}>
                    {reason === "unused" ? `Pause for ${pauseMonths} ${pauseMonths === 1 ? "month" : "months"}` : ACCEPT_LABEL[reason]}
                  </Button>
                </>
              ) : null}
              {step === 2 ? (
                <HoldToConfirmButton onConfirm={() => setOutcome({ kind: "cancelled" })} confirmedContent="Cancelled">
                  Hold to cancel plan
                </HoldToConfirmButton>
              ) : null}
            </div>
          </div>
        </div>
      )}
    </BlockFrame>
  );
}

