/** Why a clinic wants to cancel. */
export type ReasonId = "price" | "unused" | "feature" | "switching";

/** One reason card. */
export interface Reason {
  id: ReasonId;
  label: string;
  helper: string;
}

/** The reasons, in the order the cards show them. */
export const REASONS: Reason[] = [
  { id: "price", label: "It costs too much", helper: "The plan is more than we can spend right now." },
  { id: "unused", label: "We do not use it enough", helper: "Bookings are slow, or the team has not settled in." },
  { id: "feature", label: "Something is missing", helper: "We need a feature Fernhill does not have yet." },
  { id: "switching", label: "We are moving to another tool", helper: "Our group picked a different system." },
];

/** The three steps of cancelling. */
export const CANCEL_STEPS = [
  { id: "reason", label: "Reason" },
  { id: "offer", label: "Options" },
  { id: "confirm", label: "Confirm" },
] as const;

/** The plan being cancelled. */
export const PLAN = { name: "Clinic", seats: 6, price: 89, renews: "Dec 1, 2026" };

/** The cheaper plan offered when price is the reason. */
export const LOWER_PLAN = { name: "Solo", price: 29, seats: 1 };

/** The pause lengths on offer, in months. */
export const PAUSE_MONTHS = [1, 2, 3] as const;

/** The date a pause of `months` ends, counted from the renewal. */
export function pauseEnds(months: number) {
  return ["Jan 1, 2027", "Feb 1, 2027", "Mar 1, 2027"][months - 1] ?? "Jan 1, 2027";
}

"use client";

import { useEffect, useId, useState } from "react";

import { NumberTicker } from "@/components/motion/number-ticker";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { Textarea } from "@/components/ui/textarea";

import { BulbIcon, DiscountIcon, ExportIcon, PauseCalendarIcon } from "../icons";
import { LOWER_PLAN, PAUSE_MONTHS, pauseEnds, PLAN, type ReasonId } from "./data";

/** Props for the option tailored to a reason. */
export interface OfferPanelProps {
  reason: ReasonId;
  pauseMonths: number;
  onPauseMonths: (months: number) => void;
  note: string;
  onNote: (note: string) => void;
}

const WHOLE: Intl.NumberFormatOptions = { maximumFractionDigits: 0 };
const PAUSE_OPTIONS = PAUSE_MONTHS.map((months) => ({ value: String(months), label: months === 1 ? "1 month" : `${months} months` }));

/** The monthly price each reason's option leads to. */
export const offerPrice = (reason: ReasonId) => (reason === "price" ? LOWER_PLAN.price : reason === "unused" ? 0 : PLAN.price);

/**
 * One option that answers the chosen reason: a cheaper plan, a pause of one
 * to three months, a note to the team, or an export. The monthly price rolls
 * from today's to the option's. It is a choice, never a wall: the cancel path
 * stays beside it.
 */
export function OfferPanel({ reason, pauseMonths, onPauseMonths, note, onNote }: OfferPanelProps) {
  const noteId = useId();
  // Start on today's price, then roll to the option's once it is on screen.
  const [shownPrice, setShownPrice] = useState(PLAN.price);
  useEffect(() => {
    const frame = requestAnimationFrame(() => setShownPrice(offerPrice(reason)));
    return () => cancelAnimationFrame(frame);
  }, [reason]);

  const price = (
    <p className="text-sm text-muted-foreground">
      Your price:{" "}
      <span className="text-2xl font-semibold text-foreground tabular-nums">
        $<NumberTicker value={shownPrice} format={WHOLE} />
      </span>{" "}
      a month
    </p>
  );

  if (reason === "price") {
    return (
      <div className="flex flex-col gap-3">
        <h3 className="flex items-center gap-2 text-base font-semibold">
          <DiscountIcon aria-hidden="true" className="size-4 text-chart-1" />
          Move to {LOWER_PLAN.name} instead
        </h3>
        <p className="text-sm">Keep your patients, history and booking page for ${LOWER_PLAN.price} a month. {LOWER_PLAN.name} covers one practitioner.</p>
        {price}
      </div>
    );
  }

  if (reason === "unused") {
    return (
      <div className="flex flex-col gap-3">
        <h3 className="flex items-center gap-2 text-base font-semibold">
          <PauseCalendarIcon aria-hidden="true" className="size-4 text-chart-1" />
          Pause instead of cancelling
        </h3>
        <p className="text-sm">Bookings close while paused. Everything is kept, and billing starts again on {pauseEnds(pauseMonths)}.</p>
        <SegmentedControl aria-label="Pause length" options={PAUSE_OPTIONS} value={String(pauseMonths)} onValueChange={(value) => onPauseMonths(Number(value))} />
        {price}
      </div>
    );
  }

  if (reason === "feature") {
    return (
      <div className="flex flex-col gap-3">
        <h3 className="flex items-center gap-2 text-base font-semibold">
          <BulbIcon aria-hidden="true" className="size-4 text-chart-1" />
          Tell us what is missing
        </h3>
        <label htmlFor={noteId} className="text-sm">
          The product team reads every note and replies within two working days.
        </label>
        <Textarea id={noteId} rows={3} value={note} placeholder="We need group classes with a waiting list." onChange={(event) => onNote(event.target.value)} />
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-3">
      <h3 className="flex items-center gap-2 text-base font-semibold">
        <ExportIcon aria-hidden="true" className="size-4 text-chart-1" />
        Take your data with you
      </h3>
      <p className="text-sm">Download patients, visits and invoices as spreadsheet files, ready to import into your next system.</p>
    </div>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { useId, useRef } from "react";

