import type { Reason, ReasonId } from "./data";

/** Props for the reason cards. */
export interface ReasonCardsProps {
  reasons: Reason[];
  value: ReasonId | null;
  onChange: (id: ReasonId) => void;
}

/**
 * Four reason cards as one radio group. The highlight glides to the chosen
 * card. Arrows move and choose and wrap at the ends; Home and End go to the
 * first and last. With nothing chosen yet, Tab lands on the first card.
 */
export function ReasonCards({ reasons, value, onChange }: ReasonCardsProps) {
  const groupRef = useRef<HTMLDivElement>(null);
  const glideId = useId();
  const reduceMotion = useReducedMotion();
  const index = reasons.findIndex((reason) => reason.id === value);

  return (
    <div
      ref={groupRef}
      role="radiogroup"
      aria-label="Why are you cancelling?"
      className="grid gap-2 @lg:grid-cols-2"
      onKeyDown={(event) => {
        const next = rovingIndex(event, Math.max(0, index), reasons.length);
        const reason = next === null ? undefined : reasons[next];
        if (next === null || !reason) return;
        event.preventDefault();
        onChange(reason.id);
        focusRoving(groupRef.current, next);
      }}
    >
      {reasons.map((reason, position) => {
        const checked = reason.id === value;
        return (
          <div
            key={reason.id}
            role="radio"
            aria-checked={checked}
            tabIndex={checked || (index === -1 && position === 0) ? 0 : -1}
            data-roving={position}
            onClick={() => onChange(reason.id)}
            onKeyDown={(event) => {
              if (event.key === " " || event.key === "Enter") {
                event.preventDefault();
                onChange(reason.id);
              }
            }}
            className="relative isolate flex cursor-pointer flex-col gap-1 rounded-xl border border-border p-4 outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            {checked ? (
              <motion.span
                layoutId={glideId}
                aria-hidden="true"
                className="absolute -inset-px -z-10 rounded-xl border-2 border-chart-1 bg-chart-1/10"
                transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 42 }}
              />
            ) : null}
            <span className="text-sm font-medium">{reason.label}</span>
            <span className="text-xs text-muted-foreground">{reason.helper}</span>
          </div>
        );
      })}
    </div>
  );
}

import type { KeyboardEvent } from "react";

/** Which arrow keys step through a list. */
export type RovingAxis = "vertical" | "horizontal" | "both";

const BACK = { vertical: ["ArrowUp"], horizontal: ["ArrowLeft"], both: ["ArrowUp", "ArrowLeft"] } as const;
const FORWARD = { vertical: ["ArrowDown"], horizontal: ["ArrowRight"], both: ["ArrowDown", "ArrowRight"] } as const;

/**
 * Reads one key press on a list of `count` items and returns the index it
 * moves to, or null for a key the list does not handle. Arrows step and wrap
 * at the ends; Home and End go to the first and last item. The caller
 * prevents the default only when an index comes back.
 */
export function rovingIndex(event: KeyboardEvent, current: number, count: number, axis: RovingAxis = "both"): number | null {
  if (count === 0) return null;
  const back: readonly string[] = BACK[axis];
  const forward: readonly string[] = FORWARD[axis];
  if (back.includes(event.key)) return (current - 1 + count) % count;
  if (forward.includes(event.key)) return (current + 1) % count;
  if (event.key === "Home") return 0;
  if (event.key === "End") return count - 1;
  return null;
}

/** Moves focus to the element in `container` that carries `data-roving` equal to `index`, after React has painted. */
export function focusRoving(container: HTMLElement | null, index: number) {
  requestAnimationFrame(() => {
    container?.querySelector<HTMLElement>(`[data-roving="${index}"]`)?.focus();
  });
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useRef, useState } from "react";

/** Props for a box whose height follows its content on a spring. */
export interface SpringHeightProps {
  children: ReactNode;
  className?: string;
}

/**
 * Measures its content and springs its own height to match, with no bounce,
 * so whatever sits under it glides instead of jumping. Under reduced motion
 * the height changes at once.
 */
export function SpringHeight({ children, className }: SpringHeightProps) {
  const innerRef = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState<number | "auto">("auto");
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    const inner = innerRef.current;
    if (!inner) return;
    const observer = new ResizeObserver(([entry]) => {
      if (entry) setHeight(entry.borderBoxSize[0]?.blockSize ?? entry.contentRect.height);
    });
    observer.observe(inner);
    return () => observer.disconnect();
  }, []);

  return (
    <motion.div
      initial={false}
      animate={{ height }}
      transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 360, damping: 38 }}
      className="overflow-hidden"
    >
      <div ref={innerRef} className={className}>
        {children}
      </div>
    </motion.div>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";

import { CheckIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

/** Props for the rail of setup steps. */
export interface StepRailProps {
  steps: readonly { id: string; label: string }[];
  current: number;
  /** Names the marker so two rails on a page never share one. */
  railId: string;
  /** Stacks the steps once the frame is wide. Off, they always run across. */
  stackWhenWide?: boolean;
}

/**
 * The steps of a guided setup, in order, with a marker that glides to the
 * current one. Done steps show a tick. Under reduced motion the marker jumps.
 */
export function StepRail({ steps, current, railId, stackWhenWide = false }: StepRailProps) {
  const reduceMotion = useReducedMotion();
  return (
    <ol className={cn("flex gap-1", stackWhenWide && "@xl:flex-col")} aria-label="Steps">
      {steps.map((step, index) => {
        const done = index < current;
        const here = index === current;
        return (
          <li
            key={step.id}
            aria-current={here ? "step" : undefined}
            className={cn("relative isolate flex flex-1 items-center gap-2 rounded-lg px-2.5 py-2 text-sm", stackWhenWide && "@xl:flex-none", here ? "font-medium" : "text-muted-foreground")}
          >
            {here ? (
              <motion.span
                layoutId={`${railId}-marker`}
                aria-hidden="true"
                className="absolute inset-0 -z-10 rounded-lg bg-muted"
                transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 460, damping: 40 }}
              />
            ) : null}
            <span
              aria-hidden="true"
              className={cn(
                "flex size-5 shrink-0 items-center justify-center rounded-full border text-xs tabular-nums",
                done ? "border-transparent bg-chart-2 text-primary-foreground" : here ? "border-foreground" : "border-border",
              )}
            >
              {done ? <CheckIcon className="size-3" /> : index + 1}
            </span>
            <span className="hidden truncate @md:inline">{step.label}</span>
            <span className="sr-only @md:hidden">{step.label}</span>
            {done ? <span className="sr-only">, done</span> : null}
          </li>
        );
      })}
    </ol>
  );
}
